	// InvestigateRunID is the 12-hex-char ID of the parent investigation
	// run when Kind is an investigate kind. Multiple sessions across rounds
	// share this ID so the loop driver can correlate them. Empty for
	// non-investigate sessions.
	InvestigateRunID string `json:"investigate_run_id,omitempty"`

	// InvestigateTopic is the human-readable topic the investigation was
	// asked to investigate. Snapshot at session start so checkpoint
	// metadata records what the agent was investigating. Only meaningful
	// when Kind is an investigate kind.
	InvestigateTopic string `json:"investigate_topic,omitempty"`

	// TurnID is a unique identifier for the current agent turn.
	// Lifecycle:
	//   - Generated fresh in InitializeSession at each turn start
	//   - Shared across all checkpoints within the same turn
	//   - Used to correlate related checkpoints when a turn's work spans multiple commits
	//   - Persists until the next InitializeSession call generates a new one
	TurnID string `json:"turn_id,omitempty"`

	// TurnCheckpointIDs tracks all checkpoint IDs condensed during the current turn.
	// Lifecycle:
	//   - Set in PostCommit when a checkpoint is condensed for an ACTIVE session
	//   - Consumed in HandleTurnEnd to finalize all checkpoints with the full transcript
	//   - Cleared in HandleTurnEnd after finalization completes
	//   - Cleared in InitializeSession when a new prompt starts
	//   - Cleared when session is reset (ResetSession deletes the state file entirely)
	TurnCheckpointIDs []string `json:"turn_checkpoint_ids,omitempty"`

	// LastInteractionTime is updated on agent-interaction events (TurnStart,
	// TurnEnd, SessionStop, Compaction) but NOT on git commit hooks.
	// Used for stale session detection in "entire doctor".
	LastInteractionTime *time.Time `json:"last_interaction_time,omitempty"`

	// CaptureDegradedAt records when the session's most recent turn degraded
	// capture because a bounded capture operation exceeded its budget. Set at
	// turn end, cleared by the next healthy turn, and surfaced by `entire status`.
	CaptureDegradedAt *time.Time `json:"capture_degraded_at,omitempty"`

	// StepCount is the number of checkpoints/steps created in this session.
	// JSON tag kept as "checkpoint_count" for backward compatibility with existing state files.
	StepCount int `json:"checkpoint_count"`

	// CheckpointTranscriptStart is the transcript line offset where the current
	// checkpoint cycle began. Set to 0 at session start, updated to current
	// transcript length after each condensation. Used to scope the transcript
	// for checkpoint condensation: "everything since last checkpoint".
	CheckpointTranscriptStart int `json:"checkpoint_transcript_start,omitempty"`

	// CheckpointTranscriptSize is the byte size of the transcript at last condensation.
	// Used for fast "has new content?" checks in PostCommit: compare the git blob size
		return nil
	}

	return splitPromptContent(content)
}

// errPartialState signals InitializeSession's mutation callback that the
// loaded state has an empty BaseCommit (left over from a concurrent warning
// that wrote partial state). The caller falls through to initializeSession
// to repair it.
var errPartialState = errors.New("partial session state")

// HandleTurnEnd dispatches strategy-specific actions emitted when an agent turn ends.
// The primary job is to finalize all checkpoints from this turn with the full transcript.
//
// During a turn, PostCommit writes provisional transcript data (whatever was available
// at commit time). HandleTurnEnd replaces that with the complete session transcript
// (from prompt to stop event), ensuring every checkpoint has the full context.
//

func (s *ManualCommitStrategy) HandleTurnEnd(ctx context.Context, state *SessionState) error { //nolint:unparam // error return is part of the hook contract; callers check it
	hadMidTurnCommits := len(state.TurnCheckpointIDs) > 0

	// Finalize all checkpoints from this turn with the full transcript.
	//
	// IMPORTANT: This is best-effort - errors are logged but don't fail the hook.
	// Failing here would prevent session cleanup and could leave state inconsistent.
	// The provisional transcript from PostCommit is already persisted, so the
	// checkpoint isn't lost - it just won't have the complete transcript.
	errCount := s.finalizeAllTurnCheckpoints(ctx, state)
	if errCount > 0 {
		logCtx := logging.WithComponent(ctx, "checkpoint")
		logging.Warn(logCtx, "HandleTurnEnd completed with errors (best-effort)",
			slog.String("session_id", state.SessionID),
			slog.Int("error_count", errCount),
		)
	}

	// Advance CheckpointTranscriptStart to the actual transcript end after
	// mid-turn commits. When an agent commits mid-turn (e.g., Codex "commit/push"),
	// condensation records TotalTranscriptLines at commit time, but the agent
	// continues writing to the transcript (tool results, token counts, task_complete).
	// Without this fix, the next checkpoint's scoped transcript starts mid-turn,
	// including a tail of already-condensed content.
	//
	// Skip this when carry-forward is active. carryForwardToNewShadowBranch
	// intentionally resets CheckpointTranscriptStart to 0 so the next checkpoint
	// remains self-contained with the full transcript.
	if hadMidTurnCommits && state.TranscriptPath != "" && len(state.FilesTouched) == 0 {
		transcriptPath, resolveErr := resolveTranscriptPath(state)
		if resolveErr == nil {
			if ag, agErr := agent.GetByAgentType(state.AgentType); agErr == nil {
				if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
					if pos, posErr := analyzer.GetTranscriptPosition(transcriptPath); posErr == nil && pos > state.CheckpointTranscriptStart {
						logging.Debug(logging.WithComponent(ctx, "hooks"),
							"advancing CheckpointTranscriptStart to turn end after mid-turn commit",
							slog.String("session_id", state.SessionID),
							slog.Int("old_offset", state.CheckpointTranscriptStart),
							slog.Int("new_offset", pos),
						)
						state.CheckpointTranscriptStart = pos
					}
				}
			}
		}
	}

	return nil
}

// precomputeTranscriptBlobsForFinalize chunks + zlib-compresses the redacted
// transcript once for reuse across every checkpoint in the turn. Returns nil
// (without error) when the transcript is empty — downstream stores skip
// transcript updates in that case, so precompute would only write a wasted
// empty-chunk blob to the object store. On failure, logs a warning and
// returns nil so the loop falls back to per-checkpoint chunking.
func precomputeTranscriptBlobsForFinalize(ctx context.Context, repo *git.Repository, transcript redact.RedactedBytes, state *SessionState) *checkpoint.PrecomputedTranscriptBlobs {
	if transcript.Len() == 0 {
		return nil
	}
	_, span := perf.Start(ctx, "precompute_transcript_blobs")
	defer span.End()
	precomputed, err := checkpoint.PrecomputeTranscriptBlobs(ctx, repo, transcript, state.AgentType)
	if err != nil {
		logging.Warn(ctx, "finalize: precompute transcript blobs failed, falling back to per-checkpoint work",
			slog.String("session_id", state.SessionID),
			slog.String("error", err.Error()),
		)
		return nil
	}
	return precomputed
}

// redactFinalizedTranscript redacts the finalized full-session transcript,
// delegating to redactSessionTranscript so finalize and post-commit condensation
// share one pipeline. That sharing is load-bearing, not tidiness: both store the
// same sanitized, image-externalized bytes for the same session under the same
// prefix-cache key, so a divergence between them would splice a prefix produced
// by one pipeline onto a suffix produced by the other. Going through the same
// function -- including its injectable redactSessionJSONLBytes seam -- makes that
// impossible rather than merely unlikely.
//
// ok=false means abandon this finalize pass, and is returned only for a degraded
// scanner -- the caller keeps TurnCheckpointIDs so a repeated Stop process can
// retry, since the degradation flag is per-process. Any other redaction failure
// drops the transcript and returns ok=true, preserving the rest of the checkpoint
// metadata: hooks have no retry path, and partial metadata beats none.
func redactFinalizedTranscript(
	logCtx context.Context,
	repo *git.Repository,
	sessionID string,
	fullTranscript []byte,
) (transcript redact.RedactedBytes, ok bool) {
	redacted, _, err := redactSessionTranscript(logCtx, repo, sessionID, fullTranscript)
	if err == nil {
		return redacted, true
	}

	if errors.Is(err, redact.ErrScannerDegraded) {
		logging.Warn(logCtx, "finalize: transcript redaction degraded, skipping",
			slog.String("session_id", sessionID),
			slog.String("error", err.Error()),
		)
		return redact.RedactedBytes{}, false
	}

	logging.Warn(logCtx, "finalize: transcript redaction failed, dropping transcript",
		slog.String("session_id", sessionID),
		slog.String("error", err.Error()),
	)
	return redact.RedactedBytes{}, true
}

// finalizeAllTurnCheckpoints replaces the provisional transcript in each checkpoint
// created during this turn with the full session transcript.
//
// This is called at turn end (stop hook). During the turn, PostCommit wrote whatever
// transcript was available at commit time. Now we have the complete transcript and
// replace it so every checkpoint has the full prompt-to-stop context.
//
// Returns the number of errors encountered (best-effort: continues processing on error).
func (s *ManualCommitStrategy) finalizeAllTurnCheckpoints(ctx context.Context, state *SessionState) int {
	if len(state.TurnCheckpointIDs) == 0 {
		return 0 // No mid-turn commits to finalize
	}
	budget := s.turnCheckpointFinalizeBudget
	if budget == 0 {
		budget = defaultTurnCheckpointFinalizeBudget
	}
	ctx, cancel := context.WithTimeout(ctx, budget)
	defer cancel()

	logCtx := logging.WithComponent(ctx, "checkpoint")

	logging.Info(logCtx, "finalizing turn checkpoints with full transcript",
		slog.String("session_id", state.SessionID),
		slog.Int("checkpoint_count", len(state.TurnCheckpointIDs)),
	)

	errCount := 0

	// Read full transcript from live transcript file, re-resolving the path if the
	// agent relocated it mid-session (e.g., Cursor CLI flat → nested layout change).
	if state.TranscriptPath == "" {
		logging.Warn(logCtx, "finalize: no transcript path, skipping",
			slog.String("session_id", state.SessionID),
		)
		state.TurnCheckpointIDs = nil
		return 1 // Count as error - all checkpoints will be skipped
	}

	transcriptPath, resolveErr := resolveTranscriptPath(state)
	if resolveErr != nil {
		logging.Warn(logCtx, "finalize: transcript path resolution failed, skipping",
			slog.String("session_id", state.SessionID),
			slog.Any("error", resolveErr),
		)
		state.TurnCheckpointIDs = nil
		return 1 // Count as error - all checkpoints will be skipped
	}

	fullTranscript, err := os.ReadFile(transcriptPath) //nolint:gosec // path validated by resolveTranscriptPath
	if err != nil || len(fullTranscript) == 0 {
		msg := "finalize: empty transcript, skipping"
		if err != nil {
			msg = "finalize: failed to read transcript, skipping"
		}
		logging.Warn(logCtx, msg,
			slog.String("session_id", state.SessionID),
			slog.String("transcript_path", state.TranscriptPath),
			slog.Any("error", err),
		)
		state.TurnCheckpointIDs = nil
		return 1 // Count as error - all checkpoints will be skipped
	}

	// Open repository (needed for shadow branch prompt reading and checkpoint store)
	repo, err := OpenRepository(ctx)
	if err != nil {
		logging.Warn(logCtx, "finalize: failed to open repository",
			slog.String("error", err.Error()),
		)
		state.TurnCheckpointIDs = nil
		return 1 // Count as error - all checkpoints will be skipped
	}
	defer repo.Close()
	policy, err := readLocalCheckpointPolicy(logCtx, repo)
	if err != nil {
		warnOrLogCheckpointPolicyReadFailure(logCtx, err)
		state.TurnCheckpointIDs = nil
		return 1
	}
	if !checkpointpolicy.CanSatisfyPolicy(policy) {
		warnIfCheckpointPolicyNeedsUpgrade(logCtx, policy)
		state.TurnCheckpointIDs = nil
		return 1
	}

	prompts := readPromptsFromShadowBranch(ctx, repo, state)
	if len(prompts) == 0 {
		prompts = readPromptsFromFilesystem(ctx, state.SessionID)
	}

	ag, _ := agent.GetByAgentType(state.AgentType) //nolint:errcheck // ag may be nil for unknown agent types; ExtractSkillEvents handles nil
	// Persist newly extracted events into state (the caller's MutateSessionState
	// saves them); telemetry for them is emitted by the lifecycle turn-end
	// handler, which snapshots state.SkillEvents growth around HandleTurnEnd.
	_, skillEvents := persistNewSkillEvents(state, agent.ExtractSkillEvents(ctx, ag, fullTranscript, 0))

	// Sanitize before externalizing and redacting, matching CondenseSession's
	// sanitize -> externalize -> redact order. Skill events above are extracted from
	// the pre-sanitization bytes because they are session telemetry rather than
	// stored transcript content.
	fullTranscript = agent.SanitizeTranscriptForStorage(ag, fullTranscript)

	// Redact secrets before writing. Checkpoint store methods require
	// pre-redacted in-memory transcript content from callers. The live
	// transcript on disk is still treated as raw/untrusted input, so redact it
	// here before anything is persisted to the metadata branch.
	//
	// On failure: drop the transcript but continue writing checkpoint metadata
	// (attribution, files touched, prompts). Hooks run without user interaction
	// so there is no retry path — preserving partial metadata is better than
	// losing everything. Persisting an unredacted transcript would be worse.
	// Run the regex-only pipeline over the transcript — OPF runs later in
	// the pre-push rewrite path, which re-redacts these regex-only blobs
	// and produces OPF-applied (9-layer) commits before the push goes out.
	// Externalize inline images BEFORE redaction, mirroring CondenseSession, so the
	// finalized (authoritative, full-session) transcript keeps its placeholders and
	// matching assets instead of re-inlining what condensation lifted out. Opt-in;
	// a no-codec agent or a transcript with no images is a no-op.
	var finalizeAssets []checkpoint.TranscriptAsset
	// Whether externalization actually RAN at finalize. When it did not (flag
	// off here even though it may have been on at condensation — e.g. an
	// ENTIRE_EXTERNALIZE_IMAGES env override not inherited by the hook
	// process, or settings toggled mid-session), an empty finalizeAssets means
	// "extraction didn't run", NOT "the transcript has no images" — clearing
	// the previously-stored assets would permanently lose them (the re-inlined
	// base64 is destroyed by redaction below).
	externalizationRan := false
	if settings.IsImageExternalizationEnabled(ctx) {
		rewritten, assets, exErr := extractSessionImages(state.AgentType, fullTranscript)
		if exErr != nil {
			logging.Warn(logCtx, "finalize: image externalization failed; leaving transcript inline",
				slog.String("session_id", state.SessionID),
				slog.String("error", exErr.Error()),
			)
		} else {
			fullTranscript = rewritten
			finalizeAssets = assets
			externalizationRan = true
		}
	}
	// Re-capture sidecar images (e.g. Cursor's SQLite store) so a finalize that
	// rewrites the transcript re-writes them too. When the full transcript differs
	// from the stored (mid-turn) one, writeAssets clears the whole assets/ folder
	// and re-writes only these assets — omitting the sidecar images here would drop
	// what CondenseSession captured. Content-hash names make this idempotent with
	// condensation's write; when the transcript is unchanged, writeAssets is not
	// called and condensation's assets are left intact.
	finalizeAssets = append(finalizeAssets, sidecarSessionImages(ctx, logCtx, ag, state)...)
	// Sidecar capture is best-effort: a transient miss here (sqlite3 locked/timed
	// out) yields no assets. For a sidecar-capable agent, preserve the assets a
	// prior condensation stored rather than letting an empty set clear them.
	_, sidecarCapable := agent.AsSidecarImageProvider(ag)

	redactedTranscript, redactOK := redactFinalizedTranscript(logCtx, repo, state.SessionID, fullTranscript)
	if !redactOK {
		return 1
	}

	// Post-commit emits regex-only blobs; the writer joins + redacts
	// via checkpoint.redactedJoinedPrompts. OPF runs later, once per
	// push, in the pre-push rewrite path.
	// The hook store envelope (see hookCheckpointStoreOptions): the transcript
	// finalize targets existing checkpoints whose refs — and, on a partial
	// clone, whose blobs — may live only on the remote (resumed/adopted
	// multi-machine sessions). This loops over every checkpoint of the turn
	// against one store, so both fetch paths need their own memo or a dead
	// network costs the budget N times: gitRefsStore.fetchFailure covers refs,
	// and hookBlobFetcher memoizes an exhausted blob fetch. The context enclosing
	// this finalize pass bounds slow successes, which neither memo can detect.
	stores, err := checkpoint.Open(ctx, repo, s.hookCheckpointStoreOptions(ctx))
	if err != nil {
		logging.Warn(logCtx, "finalize: failed to open checkpoint store",
			slog.String("error", err.Error()),
		)
		return 1 // Count as error - all checkpoints will be skipped
	}
	store := stores.Persistent

	precomputed := precomputeTranscriptBlobsForFinalize(logCtx, repo, redactedTranscript, state)
	updateOpts := checkpoint.UpdateOptions{
		SessionID:               state.SessionID,
		Transcript:              redactedTranscript,
		Assets:                  finalizeAssets,
		PreserveAssetsWhenEmpty: sidecarCapable || !externalizationRan,
		Prompts:                 prompts,
		Agent:                   state.AgentType,
		SkillEvents:             skillEvents,
		PrecomputedBlobs:        precomputed,
	}
	errCount += finalizeTurnCheckpointWrites(ctx, logCtx, store, state, updateOpts)

	// Clear turn checkpoint IDs. Do NOT update CheckpointTranscriptStart here — it was
	// already set correctly by PostCommit: condenseAndUpdateState sets it to the total
	// transcript lines when condensing, and carryForwardToNewShadowBranch resets it to 0
	// when carry-forward is active. Overwriting here would break carry-forward by making
	// sessionHasNewContent think the transcript is fully consumed (no growth).
	state.TurnCheckpointIDs = nil

	return errCount
}

func finalizeTurnCheckpointWrites(
	ctx context.Context,
	logCtx context.Context,
	store checkpoint.PersistentStore,
	state *SessionState,
	updateOpts checkpoint.UpdateOptions,
) int {
	errCount := 0
	for checkpointIndex, cpIDStr := range state.TurnCheckpointIDs {
		if errors.Is(ctx.Err(), context.DeadlineExceeded) {
			remaining := len(state.TurnCheckpointIDs) - checkpointIndex
			errCount += remaining
			recordTurnCheckpointFinalizeDegraded(logCtx, state, remaining)
			break
		}

		cpID, err := id.NewCheckpointID(cpIDStr)
		if err != nil {
			logging.Warn(logCtx, "finalize: invalid checkpoint ID, skipping",
				slog.String("checkpoint_id", cpIDStr),
				slog.String("error", err.Error()),
			)
			errCount++
			continue
		}

		updateOpts.CheckpointID = cpID
		if err := store.Write(ctx, checkpoint.SessionTranscript(updateOpts)); err != nil {
			logging.Warn(logCtx, "finalize: failed to update checkpoint",
				slog.String("checkpoint_id", cpIDStr),
				slog.String("error", err.Error()),
			)
			errCount++
			if errors.Is(ctx.Err(), context.DeadlineExceeded) {
				remaining := len(state.TurnCheckpointIDs) - checkpointIndex - 1
				errCount += remaining
				recordTurnCheckpointFinalizeDegraded(logCtx, state, remaining+1)
				break
			}
			continue
		}

		logging.Info(logCtx, "finalize: checkpoint updated with full transcript",
			slog.String("checkpoint_id", cpIDStr),
			slog.String("session_id", state.SessionID),
		)
	}
	return errCount
}

func recordTurnCheckpointFinalizeDegraded(logCtx context.Context, state *SessionState, unfinalized int) {
	now := time.Now().UTC()
	state.CaptureDegradedAt = &now
	logging.Warn(logCtx, "finalize: total deadline exceeded; checkpoints left with provisional transcripts",
		slog.String("session_id", state.SessionID),
		slog.Int("unfinalized_count", unfinalized),
	)
}

// filesChangedInCommit returns the set of files changed in a commit using git diff-tree.
// Uses the git CLI for faster performance vs go-git tree walks (lower constant factors).
// Falls back to go-git tree walk if git diff-tree fails, since an empty result would
// break downstream condensation and carry-forward logic.
func filesChangedInCommit(ctx context.Context, repoDir string, commit *object.Commit, headTree, parentTree *object.Tree) map[string]struct{} {
	var parentHash string
	if commit.NumParents() > 0 {
		parentHash = commit.ParentHashes[0].String()
	}
	result, err := gitops.DiffTreeFiles(ctx, repoDir, parentHash, commit.Hash.String())
	if err != nil {
