Explain provides human-readable context about sessions, commits, and checkpoints.

Use this command to understand what happened during agent-driven development,
either for self-review or to understand a teammate's work.

By default, shows checkpoints on the current branch. Pass a checkpoint ID or
commit SHA as a positional argument to explain a specific item, or use flags.

Viewing specific items:
  entire checkpoint explain <id-or-sha>           Auto-detects checkpoint ID or commit SHA
  entire checkpoint explain --checkpoint <id>     Force interpretation as checkpoint ID
  entire checkpoint explain --commit <ref>        Force interpretation as commit ref

Checkpoints in another repo:
  entire checkpoint explain <id> --repo owner/name
                 Explain a checkpoint owned by another repository — the
                 drill-down for a cross-repo 'entire search' hit. Reads it from
                 that repo's Entire API; nothing is written to this repo.
                 Needs a full checkpoint ID (positional or --checkpoint) and a
                 checkpoint that has been pushed.

Filtering the list view:
  --session      Filter checkpoints by session ID (or prefix)

Output verbosity levels (when explaining a specific item):
  Default:         Detailed view with scoped prompts (ID, session, tokens, intent, prompts, files)
  --short          Summary only (ID, session, timestamp, tokens, intent)
  --full           Parsed full transcript (all prompts/responses from entire session)
  --raw-transcript Raw transcript file (JSONL format)

Machine-readable export modes (additive surface for external consumers):
  --json           Metadata-only JSON. Lists checkpoints when no target is given;
                   emits a single checkpoint envelope when a target is supplied.
                   Transcript bytes are NEVER embedded in the JSON envelope.
  --transcript     Stream stored checkpoint transcript bytes (JSONL) to stdout
                   for the selected session. Same bytes as --raw-transcript
                   while checkpoints v1 is the checkpoint store.
  --session-index  Pick a session within a multi-session checkpoint (0-based).
                   Defaults to the latest session. Only meaningful with
                   --transcript or --raw-transcript.
  --limit          Cap the number of checkpoints returned by the list view.
                   Defaults to 100. When the cap is hit, a stderr note
                   says how many were skipped. Only meaningful with --json.

Summary generation:
  --generate    Generate an AI summary for the checkpoint
  --force       Regenerate even if a summary already exists (requires --generate)

Performance options:
  --search-all  Remove branch/depth limits when searching for commits (may be slow)

Checkpoint detail view shows:
  - Author of the checkpoint
  - Associated git commits that reference the checkpoint
  - Prompts and responses from the session

Note: --session filters the list view; the positional arg, --commit, and --checkpoint are mutually exclusive.

Usage:
  entire checkpoint explain [checkpoint-id | commit-sha] [flags]

Flags:
  -c, --checkpoint string             Explain a specific checkpoint (ID or prefix)
      --commit string                 Explain a specific commit (SHA or ref, "commit-ish")
      --force                         Regenerate summary even if one already exists (requires --generate)
      --full                          Show full parsed transcript (all prompts/responses)
      --generate                      Generate an AI summary for the checkpoint
  -h, --help                          help for explain
      --insecure-http-auth            Allow plain-HTTP auth for --repo (local dev only)
      --json                          Output metadata as JSON (no transcript bytes)
      --limit int                     Cap the list view at N checkpoints (default: 100). Only meaningful with --json.
      --no-pager                      Disable pager output
      --raw-transcript                Show raw transcript file (JSONL format)
      --repo string                   Explain a checkpoint owned by another repo (owner/name or gh/owner/name), read from that repo's Entire API
      --search-all                    Search all commits (no branch/depth limit, may be slow)
      --session string                Filter checkpoints by session ID (or prefix)
      --session-index int             Session index within a multi-session checkpoint (0-based, defaults to latest) (default -1)
  -s, --short                         Show summary only (omit prompts and files)
      --summary-timeout-seconds int   Hard deadline in seconds for --generate summary generation; overrides summary_timeout_seconds setting. 0 = use setting; if setting is also unset or 0, no automatic deadline applies.
      --transcript                    Stream stored checkpoint transcript bytes to stdout

Global Flags:
      --context name   Act as this saved login name for this command only, instead of the active context (entire auth contexts lists them)
package strategy

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/remote"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
)

// ManualCommitStrategy implements the manual-commit strategy for session management.
// It stores checkpoints on shadow branches and condenses session logs to a
// permanent sessions branch when the user commits.
type ManualCommitStrategy struct {
	// stateStore manages session state files in .git/entire-sessions/
	stateStore *session.StateStore
	// stateStoreOnce ensures thread-safe lazy initialization
	stateStoreOnce sync.Once
	// stateStoreErr captures any error during initialization
	stateStoreErr error

	// blobFetcher, when set, is passed to the checkpoint store to enable
	// on-demand blob fetching after treeless fetches. Set via SetBlobFetcher.
	blobFetcher checkpoint.BlobFetchFunc

	// blobFetchBudget bounds one blob fetch on a git-hook path. Zero means
	// remote.WriteProbeFetchBudget. Per-instance rather than a package var so
	// tests can shorten it without mutating process-global state, which
	// t.Parallel() makes a data race (CLAUDE.md: "Tests that modify
	// process-global state cannot be parallelized").
	blobFetchBudget time.Duration

	// turnCheckpointFinalizeBudget bounds the whole turn-finalize pass. Zero
	// means the production default.
	turnCheckpointFinalizeBudget time.Duration

	// checkpointRefFetcher overrides the hook ref fetcher in tests. Production
	// uses remote.HookCheckpointRefFetcher.
	checkpointRefFetcher checkpoint.RefFetchFunc
}

// Codex gives Stop hooks 30 seconds. Keep the network-heavy finalize pass
// below that ceiling so state persistence and the rest of turn cleanup still
// have time to finish before the host kills the process.
const defaultTurnCheckpointFinalizeBudget = 20 * time.Second

// getStateStore returns the session state store, initializing it lazily if needed.
// Thread-safe via sync.Once.
func (s *ManualCommitStrategy) getStateStore(_ context.Context) (*session.StateStore, error) {
	s.stateStoreOnce.Do(func() {
		store, err := session.NewStateStore(context.Background()) //nolint:contextcheck // sync.Once must use background context to avoid caching errors from a cancelled caller context
		if err != nil {
			s.stateStoreErr = fmt.Errorf("failed to create state store: %w", err)
			return
		}
		s.stateStore = store
	})
	return s.stateStore, s.stateStoreErr
}

func (s *ManualCommitStrategy) getCheckpointStores(ctx context.Context, repo *git.Repository) (*checkpoint.Stores, error) {
	stores, err := checkpoint.Open(ctx, repo, checkpoint.OpenOptions{BlobFetcher: s.blobFetcher, ReadRemotes: CheckpointReadRemotes(ctx)})
	if err != nil {
		return nil, fmt.Errorf("open checkpoint store: %w", err)
	}
	return stores, nil
}

// getPersistentStore returns a store bound to the resolved committed-metadata
// topology. Writes target refs.Primary; reads target refs.Read. The strategy's
// blob fetcher is wired in so reads can fetch blobs on demand after a treeless
// fetch.
func (s *ManualCommitStrategy) getPersistentStore(ctx context.Context, repo *git.Repository) (checkpoint.PersistentStore, error) {
	stores, err := s.getCheckpointStores(ctx, repo)
	if err != nil {
		return nil, err
	}
	return stores.Persistent, nil
}

// getEphemeralStore returns the git-backed shadow-branch store with the
// strategy's blob fetcher wired in.
func (s *ManualCommitStrategy) getEphemeralStore(ctx context.Context, repo *git.Repository) (checkpoint.EphemeralStore, error) {
	stores, err := s.getCheckpointStores(ctx, repo)
	if err != nil {
		return nil, err
	}
	return stores.Ephemeral(), nil
}

// NewManualCommitStrategy creates a new manual-commit strategy instance.
func NewManualCommitStrategy() *ManualCommitStrategy {
	return &ManualCommitStrategy{}
}

// SetBlobFetcher configures on-demand blob fetching for the checkpoint store.
// Must be called before the first checkpoint store access (e.g., before RestoreLogsOnly).
func (s *ManualCommitStrategy) SetBlobFetcher(f checkpoint.BlobFetchFunc) {
	s.blobFetcher = f
}

// HasBlobFetcher reports whether a blob fetcher is configured.
// Used in tests to verify the strategy is properly wired for treeless fetch support.
func (s *ManualCommitStrategy) HasBlobFetcher() bool {
	return s.blobFetcher != nil
}

